<?php /** 연차/월차/반차 관리 저장 */ use App\Core\Db; require_once __DIR__.'/../attendance/common.php'; if(!attendance_is_manager())exit; if(!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:''))exit; $pdo=Db::pdo(); $st=$pdo->prepare("INSERT INTO cpms_leave_records(employee_id,leave_date,leave_type,leave_amount,reason,created_by,created_at,updated_at) VALUES(:e,:d,:t,:a,:r,:c,:ca,:ua)"); $st->execute(array(':e'=>(int)$_POST['employee_id'],':d'=>$_POST['leave_date'],':t'=>$_POST['leave_type'],':a'=>(float)$_POST['leave_amount'],':r'=>$_POST['reason'],':c'=>attendance_employee_id($pdo),':ca'=>attendance_now(),':ua'=>attendance_now())); header('Location: ?r=관리&tab=attendance');